/** Affiliated includes occupational/cultural alignment, NOT necessarily formal legal membership. */
export const GOC_FACTION_MEMBERS:readonly FactionMember[]=Object.freeze(
GOC_NPC_INDEX_150_ABY.map((n):FactionMember=>{
 const factionId=assignments[n.id]||null,dead=n.lifeStatus==="deceased";
 return {personId:n.id,factionId,role:n.role,
 standing:dead?"historic":n.sourceClass==="sourcebook-candidate"?"unintroduced":
  factionId===null||factionId==="outer-rim-freetraders"||factionId==="neutral-relief"?"independent":"affiliated",
 visibility:["darth-korvalis","vesla-kreel","nir-varek","darth-xeran","seralyth-vhaelor"].includes(n.id)?"gm-only":"public"};
}));
/** Korvalis's association with Seralyth is creator-truth, NEVER public membership. */
